INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (1, 1, 1, 'Vo sạch gạo lứt và nấu chín.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (2, 1, 2, 'Cắt đậu hũ thành miếng và áp chảo vàng hai mặt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (3, 1, 3, 'Hấp bông cải xanh và cà rốt cho vừa chín.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (4, 1, 4, 'Sơ chế và cắt cà chua thành lát.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (5, 1, 5, 'Cho cơm, đậu hũ và rau củ ra đĩa rồi thưởng thức.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (6, 2, 1, 'Rửa sạch rau chân vịt và để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (7, 2, 2, 'Cho đậu gà đã luộc vào tô.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (8, 2, 3, 'Thêm cà chua và bơ đã cắt vào tô.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (9, 2, 4, 'Thêm rau chân vịt và trộn đều tất cả nguyên liệu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (10, 3, 1, 'Nấu nước dùng từ củ cải và cuống nấm cho ngọt nước.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (11, 3, 2, 'Áp chảo đậu hũ và xào thơm nấm đông cô.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (12, 3, 3, 'Trụng bánh phở cho vào tô, xếp nấm, đậu hũ lên trên rồi chan nước dùng nóng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (13, 4, 1, 'Phi thơm sả băm với chút ớt bột tạo màu cay thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (14, 4, 2, 'Xào nấm bào ngư và đậu hũ với gia vị cho thấm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (15, 4, 3, 'Nấu nước dùng sả, chan ngập tô bún và dùng nóng kèm rau sống.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (16, 5, 1, 'Nấu nhừ gạo thơm cùng hạt sen tươi trên lửa nhỏ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (17, 5, 2, 'Xào thơm nấm rơm và cà rốt với chút dầu ăn và gia vị.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (18, 5, 3, 'Cho nấm vào nồi cháo, khuấy đều nấu thêm 5 phút rồi tắt bếp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (19, 6, 1, 'Chiên vàng sợi đậu hũ rồi trộn đều với miến dong và thính gạo rang.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (20, 6, 2, 'Xẻ dọc ổ bánh mì, quết nước tương và tương ớt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (21, 6, 3, 'Kẹp bì chay, dưa leo cùng đồ chua vào bánh mì và thưởng thức.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (22, 7, 1, 'Xào thơm nấm đùi gà với hành boa-rô cho chín mềm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (23, 7, 2, 'Xay nhuyễn nấm cùng đậu gà chín và chút bơ thành hỗn hợp pate mịn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (24, 7, 3, 'Quết pate vào bánh mì, thêm lát bơ tươi và thưởng thức.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (25, 8, 1, 'Hầm củ cải và cà rốt lấy nước dùng ngọt thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (26, 8, 2, 'Trụng sợi hủ tiếu cho vào tô, xếp nấm xào và tàu hũ ky chiên giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (27, 8, 3, 'Chan nước dùng sôi sùng sục vào tô, rắc tiêu thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (28, 9, 1, 'Xào chín nấm bào ngư, cà rốt và bông cải xanh với chút dầu ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (29, 9, 2, 'Cho miến dong vào đảo đều tay trên lửa lớn với nước tương.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (30, 9, 3, 'Tắt bếp khi sợi miến trong và thấm đều vị.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (31, 10, 1, 'Trộn gạo nếp với hạt sen và đồ xôi trong xửng hấp 30 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (32, 10, 2, 'Đậu xanh nấu tán nhuyễn nắm thành viên hoặc rắc mặt xôi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (33, 10, 3, 'Rưới chút nước cốt dừa lên xôi đang nóng và xới đều.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (34, 11, 1, 'Xào cà chua chín mềm tạo màu đỏ tự nhiên cho nước dùng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (35, 11, 2, 'Đậu hũ non xào cùng nấm rơm nêm gia vị để nổi váng riêu thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (36, 11, 3, 'Trụng bún vào tô, múc riêu và chan nước dùng chua dịu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (37, 12, 1, 'Trộn đậu hũ tán nhuyễn với nấm mèo, nấm rơm và tiêu rồi vo viên mọc.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (38, 12, 2, 'Thả viên mọc vào nồi nước hầm rau củ đun sôi cho mọc chín nổi lên.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (39, 12, 3, 'Xếp bún vào tô và chan nước dùng kèm viên mọc thanh ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (40, 13, 1, 'Nấu bí đỏ với nước cho mềm nhừ rồi dùng muỗng dầm mịn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (41, 13, 2, 'Cho yến mạch và đậu đỏ đã ninh mềm vào khuấy đều trên lửa nhỏ 5 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (42, 13, 3, 'Nêm chút muối hồng và thưởng thức cháo sánh mịn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (43, 14, 1, 'Nấu nước dùng từ củ cải trắng và nấm hương cho trong vắt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (44, 14, 2, 'Trình bày sợi bún, xếp từng góc nấm xé, đậu hũ chiên sợi và cà rốt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (45, 14, 3, 'Chan nước dùng nóng hổi và thưởng thức hương vị thanh tao.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (46, 15, 1, 'Xào thơm nhân nấm đùi gà, mộc nhĩ, cà rốt và hạt sen với dầu hào chay.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (47, 15, 2, 'Gói nhân vào vỏ bánh bao bột mì và tạo hình múi hoa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (48, 15, 3, 'Hấp bánh chín trong xửng hơi nước 15-20 phút cho nở xốp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (49, 16, 1, 'Nấu bắp ngọt và hạt sen trong nước hầm rau củ cho chín mềm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (50, 16, 2, 'Thêm nấm đông cô thái sợi và cà rốt hạt lựu vào nấu sôi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (51, 16, 3, 'Hòa bột năng khuấy đều tạo độ sánh sệt vừa vặn cho súp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (52, 17, 1, 'Cho gạo, bí đỏ, đậu xanh và hạt sen vào nồi ninh lửa nhỏ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (53, 17, 2, 'Khi cháo chín nhừ, khuấy nhẹ cho bí đỏ hòa quyện sánh vàng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (54, 17, 3, 'Múc ra bát thưởng thức khi còn nóng ấm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (55, 18, 1, 'Xào chín nhân nấm rơm và mộc nhĩ nêm hạt nêm chay và tiêu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (56, 18, 2, 'Tráng bánh hoặc dùng bánh ướt cuộn đều phần nhân nấm thơm lừng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (57, 18, 3, 'Cắt miếng vừa ăn, rắc hành phi chay và dùng cùng nước chấm pha chua ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (58, 19, 1, 'Xào thơm măng khô đã luộc kĩ với nấm đùi gà và gia vị.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (59, 19, 2, 'Nấu nước dùng thanh ngọt rồi trút măng nấm vào ninh sôi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (60, 19, 3, 'Cho miến ra tô, chan nước dùng và rắc rau răm, tiêu sọ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (61, 20, 1, 'Pha bột bánh xèo với bột nghệ và chút nước cốt dừa cho thơm béo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (62, 20, 2, 'Đổ bột vào chảo nóng, xếp nhân nấm, đậu xanh và giá đỗ rồi đậy nắp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (63, 20, 3, 'Khi bánh giòn vàng, gấp đôi lại và dùng kèm xà lách rau thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (64, 21, 1, 'Luộc nui vừa chín tới rồi xả nước lạnh cho sợi nui săn lại.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (65, 21, 2, 'Xào thơm cà rốt, cải thìa và đậu hũ trên lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (66, 21, 3, 'Trút nui vào đảo đều cùng nước tương hảo hạng và chút dầu mè.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (67, 22, 1, 'Trộn bắp bào với đậu xanh, nấm mèo và gia vị cuốn bánh tráng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (68, 22, 2, 'Chiên chả giò ngập dầu cho vỏ bánh vàng giòn rụm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (69, 22, 3, 'Xếp bún vào tô cùng chả giò cắt khúc, chan nước mắm chua ngọt chay.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (70, 23, 1, 'Ướp nấm đùi gà với sả băm, ngũ vị hương và mật mía rồi nướng vàng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (71, 23, 2, 'Nướng hoặc hấp chả đậu hũ làm chả cơm tấm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (72, 23, 3, 'Xới cơm tấm ra đĩa, xếp sườn nấm, chả chay và dưa leo ăn kèm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (73, 24, 1, 'Xào săn cà rốt, đậu Hà Lan, bắp ngọt và đậu hũ chiên.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (74, 24, 2, 'Đổ cơm nguội vào đảo đều tay trên lửa lớn cho hạt cơm săn giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (75, 24, 3, 'Nêm gia vị chay vừa miệng, rắc hành boa-rô phi thơm lên đĩa cơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (76, 25, 1, 'Xào sơ hạt sen, nấm đông cô và cà rốt với chút dầu mè.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (77, 25, 2, 'Trộn đều phần nhân xào với cơm trắng rồi bọc gọn trong lá sen tươi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (78, 25, 3, 'Hấp gói sen trong xửng 15 phút cho hương sen thấm đượm từng hạt cơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (79, 26, 1, 'Xào nấm bào ngư và đậu hũ với nghệ tươi và dầu củ nén cho dậy mùi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (80, 26, 2, 'Nấu nước nhưn mì Quảng đậm đà ngọt từ nước dừa tươi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (81, 26, 3, 'Bày mì Quảng ra tô, chan nước nhưn xâm xấp, rắc đậu phộng rang giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (82, 27, 1, 'Trộn nấm đùi gà băm, đậu hũ tán nhuyễn với tiêu sọ, nặn thành viên chả dẹt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (83, 27, 2, 'Nướng chả trên than hoa hoặc nồi chiên không dầu cho vàng xém cạnh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (84, 27, 3, 'Pha nước mắm chay chua ngọt, thả chả nướng và cà rốt ngâm giấm vào chén.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (85, 28, 1, 'Xào nhuyễn cà chua tươi với dầu thực vật tạo thành sốt sền sệt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (86, 28, 2, 'Cho đậu hũ non và nui đã luộc vào đảo nhẹ tay kẻo nát đậu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (87, 28, 3, 'Nêm gia vị vừa ăn, rắc chút tiêu đen lên đĩa nui thơm lừng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (88, 29, 1, 'Chiên cơm trên chảo nóng với chút cà rốt hạt lựu cho hạt cơm săn ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (89, 29, 2, 'Thêm rong biển cắt sợi và nước tương nêm nếm vừa miệng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (90, 29, 3, 'Rắc mè rang vàng lên mặt cơm trước khi dọn ra bàn ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (91, 30, 1, 'Cắt đậu hũ thành khối vuông và chiên ngập dầu cho vỏ vàng ruộm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (92, 30, 2, 'Pha nước tương bần với đường, ớt tươi và nước cốt tắc đánh sủi bọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (93, 30, 3, 'Bày bún lá, đậu chiên và dưa leo lên mẹt lá chuối rồi thưởng thức.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (94, 31, 1, 'Phi thơm hành boa-rô, xào nấm đùi gà và cà rốt cho chín tới.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (95, 31, 2, 'Cho miến dong vào đảo đều với sốt xào dầu hào chay trên lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (96, 31, 3, 'Thêm cải thìa đảo nhanh tay 1 phút rồi tắt bếp dọn ra đĩa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (97, 32, 1, 'Nấu cơm niêu trên lửa nhỏ để tạo lớp cháy đáy giòn rụm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (98, 32, 2, 'Kho nấm rơm băm, đậu hũ chiên cùng nước tương, tiêu sọ cho sánh sệt đặc quánh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (99, 32, 3, 'Luộc chín bông cải xanh và cà rốt chấm cùng kho quẹt thơm nồng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (100, 33, 1, 'Chiên vắt mì sợi ngập dầu cho nở giòn rụm rồi vớt ra để ráo dầu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (101, 33, 2, 'Xào nấm đông cô, bông cải xanh và cà rốt rồi thêm nước dùng nêm vừa vị.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (102, 33, 3, 'Hòa chút bột năng tạo độ sánh cho nước sốt rồi rưới ngập lên vắt mì giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (103, 34, 1, 'Phi thơm sả băm rồi xào cà tím, nấm rơm và đậu hũ cho thấm vị tương.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (104, 34, 2, 'Nấu nước dùng từ mắm đậu chay ninh cùng thơm dứa và củ cải.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (105, 34, 3, 'Xếp bún vào tô, múc ngập nấm, cà tím rồi chan nước dùng nóng hổi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (106, 35, 1, 'Khoét ruột quả thơm lấy phần thịt cắt hạt lựu ráo nước.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (107, 35, 2, 'Chiên cơm với bột nghệ, đậu Hà Lan và thịt thơm trên lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (108, 35, 3, 'Trộn hạt điều rang giòn vào cơm và múc vào vỏ quả thơm bày biện đẹp mắt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (109, 36, 1, 'Trộn cơm gạo lứt ấm với chút dầu mè và muối hạt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (110, 36, 2, 'Trải lá rong biển lên mành tre, dàn đều cơm và xếp thanh đậu hũ, cà rốt, dưa leo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (111, 36, 3, 'Cuộn chặt tay, cắt khoanh vừa ăn và rắc mè rang lên mặt cuộn kimbap.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (112, 37, 1, 'Áp chảo sợi hủ tiếu với chút hắc xì dầu cho thơm và có màu nâu đẹp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (113, 37, 2, 'Xào chín nấm đông cô, cải thìa và đậu hũ với gia vị sốt chay.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (114, 37, 3, 'Trút hủ tiếu vào đảo nhanh tay trên lửa lớn cho hòa quyện rồi tắt bếp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (115, 38, 1, 'Chần bún gạo lứt qua nước sôi rồi xả nước lạnh để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (116, 38, 2, 'Xào chín cải thìa và đậu hũ với dầu thực vật và nước tương.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (117, 38, 3, 'Cho bún vào đảo nhẹ tay cho ngấm đều gia vị rồi múc ra đĩa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (118, 39, 1, 'Xào săn khoai tây, cà rốt và đậu gà với bột cà ri và sả băm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (119, 39, 2, 'Thêm nước hầm rau củ đun sôi cho khoai và cà rốt chín mềm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (120, 39, 3, 'Đổ nước cốt dừa vào khuấy đều sôi lăn tăn rồi chan cùng cơm nóng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (121, 40, 1, 'Nấu nước lẩu cay thơm từ ớt bột, tương ớt và nước hầm củ cải ngọt mát.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (122, 40, 2, 'Cho vắt mì, bông cải xanh và nấm kim châm vào nấu sôi 3 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (123, 40, 3, 'Thêm đậu hũ non lên trên, tắt bếp và ăn ngay khi còn sôi sùng sục.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (124, 41, 1, 'Nấu nước dùng chua ngọt từ nước cốt me chín và nước hầm củ cải ngọt mát.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (125, 41, 2, 'Xào chín nấm bào ngư và đậu hũ nêm hạt nêm chay thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (126, 41, 3, 'Cho bún, bắp chuối vào tô, múc nấm đậu hũ và chan nước dùng thanh ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (127, 42, 1, 'Cơm nguội dàn mỏng lên chảo chống dính áp chảo lửa nhỏ cho vàng giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (128, 42, 2, 'Nấu nấm rơm băm cùng nước tương, ớt tươi và đường thốt nốt cho cô đặc thành kho quẹt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (129, 42, 3, 'Bẻ từng miếng cơm cháy giòn rụm chấm ngập chén kho quẹt nấm nóng hổi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (130, 43, 1, 'Luộc măng le cho hết vị đắng rồi xào thơm với nấm rơm và gia vị.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (131, 43, 2, 'Nấu nước hầm măng cùng cà rốt cho nước ngọt đậm đà tự nhiên.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (132, 43, 3, 'Xếp bún vào tô, múc măng, nấm rơm và chan nước dùng nóng hổi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (133, 44, 1, 'Xào săn nấm đông cô, hạt sen và cà rốt với dầu mè thơm lừng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (134, 44, 2, 'Trộn nhân xào vào gạo thơm đã vo sạch và nấu cơm như bình thường.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (135, 44, 3, 'Khi cơm chín xới đều tay cho hạt sen và nấm quyện đều vào cơm thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (136, 45, 1, 'Áp chảo bánh phở trên chảo gang lửa lớn cho mặt bánh cháy cạnh thơm giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (137, 45, 2, 'Xào chín nấm đùi gà và cải thìa với nước tương và dầu hào chay sệt sánh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (138, 45, 3, 'Trút sốt nấm rau củ lên đĩa bánh phở áp chảo nóng hổi thưởng thức ngay.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (139, 46, 1, 'Trộn nấm đùi gà, nấm mèo và gia vị gói vào vỏ hoành thánh thành viên xinh xắn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (140, 46, 2, 'Luộc chín hoành thánh trong nồi nước sôi rồi vớt ra để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (141, 46, 3, 'Xếp mì sợi, hoành thánh và cải thìa vào tô rồi chan nước súp thanh trong.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (142, 47, 1, 'Trụng chín bún gạo lứt xả nước lạnh cho sợi bún tơi xốp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (143, 47, 2, 'Pha sốt mè rang với nước tương, nước cốt chanh và chút mật mía sánh mịn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (144, 47, 3, 'Trộn bún cùng dưa leo, cà rốt, đậu hũ và rưới sốt mè rắc đậu phộng lên đĩa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (145, 48, 1, 'Chiên đậu hũ vàng đều hai mặt rồi vớt ra đĩa có lót giấy thấm dầu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (146, 48, 2, 'Phi thơm hành boa-rô xào cà chua cho nhuyễn mịn thành nước sốt sánh đỏ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (147, 48, 3, 'Cho đậu hũ vào om lửa nhỏ 5 phút cho thấm đều sốt cà chua rồi tắt bếp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (148, 49, 1, 'Khía nhẹ trên mặt miếng đậu hũ để khi chiên sả ớt dễ bám vào.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (149, 49, 2, 'Phi thơm sả băm và ớt tươi trên chảo dầu nóng cho vàng giòn rồi vớt ra bát riêng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (150, 49, 3, 'Chiên đậu hũ vàng giòn hai mặt rồi trút sả ớt chiên lên mặt miếng đậu xóc đều.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (151, 50, 1, 'Hấp cách thủy cây đậu hũ non trong 5 phút cho nóng ấm rồi trút ra đĩa sâu lòng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (152, 50, 2, 'Xào thơm nấm đông cô với nước tương, dầu hào chay và chút nước dùng rau củ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (153, 50, 3, 'Hòa chút bột năng tạo độ sánh cho sốt nấm rồi rưới nhẹ nhàng lên đĩa đậu hũ non.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (154, 51, 1, 'Chiên sơ đậu hũ và nấm rơm cho săn mặt ngoài.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (155, 51, 2, 'Thắng nước màu đường thốt nốt rồi trút đậu hũ và nấm rơm vào đảo đều với nước tương.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (156, 51, 3, 'Thêm tiêu sọ xanh đập dập, đậy nắp kho liu riu 15 phút cho nước kho keo lại đậm đà.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (157, 52, 1, 'Hấp chín đậu xanh cà vỏ rồi giã nhuyễn khi còn nóng ấm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (158, 52, 2, 'Trộn đậu xanh mịn cùng nấm mèo băm nhỏ, tiêu sọ và hạt nêm chay cho dẻo quánh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (159, 52, 3, 'Gói chặt trong lá chuối tươi và hấp chín 20 phút rồi cắt khoanh bày ra đĩa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (160, 53, 1, 'Trộn bắp ngọt bào nhuyễn cùng đậu hũ ráo nước và nấm mèo băm nhỏ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (161, 53, 2, 'Cuộn nhân vào bánh tráng xốp thành những cuốn chả giò thon dài đều đặn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (162, 53, 3, 'Chiên chả giò trong dầu sôi ngập cuốn cho đến khi vỏ bánh vàng giòn rụm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (163, 54, 1, 'Phi thơm sả băm và bột cà ri cho dậy màu vàng óng ả thơm lừng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (164, 54, 2, 'Trút đậu gà chín và cà rốt vào xào săn rồi cho nước hầm rau củ đun sôi 10 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (165, 54, 3, 'Thêm nước cốt dừa vào khuấy đều cho sốt sánh ngậy rồi tắt bếp ăn kèm cơm trắng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (166, 55, 1, 'Luộc đậu gà chín mềm rồi thấm khô hoàn toàn bằng khăn sạch.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (167, 55, 2, 'Trộn đậu gà với chút dầu ăn, ớt tươi băm và muối hồng cho áo đều mặt hạt đậu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (168, 55, 3, 'Nướng trong lò hoặc nồi chiên không dầu ở 180 độ C trong 15 phút cho giòn rụm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (169, 56, 1, 'Xào thơm hành boa-rô rồi trút khoai tây và cà rốt vào đảo săn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (170, 56, 2, 'Cho đậu lăng đỏ và nước lọc vào đun sôi rồi hạ lửa nhỏ hầm liu riu 20 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (171, 56, 3, 'Khi đậu lăng nhừ sánh mịn và khoai mềm bở, nêm hạt nêm chay rồi múc ra bát.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (172, 57, 1, 'Nấu bí đỏ, đậu lăng đỏ và hạt sen trong nước sôi đến khi các nguyên liệu chín nhừ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (173, 57, 2, 'Cho toàn bộ hỗn hợp vào cối xay mịn thành chất súp sánh mượt màu vàng óng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (174, 57, 3, 'Đun sôi lại súp, nêm muối tiêu vừa ăn và trang trí chút hạt mè rang lên mặt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (175, 58, 1, 'Trải lá tàu hũ ky, xếp nấm kim châm và nấm đông cô vào giữa rồi cuộn chặt lại.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (176, 58, 2, 'Chiên áp chảo cuộn tàu hũ ky cho vàng thơm hai mặt giòn rụm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (177, 58, 3, 'Đun sôi sốt dầu hào chay với nước tương rồi cho cuộn tàu hũ ky vào rim 5 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (178, 59, 1, 'Cắt đậu hũ thành khối vuông vừa ăn rồi chiên ngập dầu cho vỏ ngoài vàng giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (179, 59, 2, 'Xay nhuyễn mè rang cùng nước tương, chút giấm táo và đường thốt nốt thành sốt sánh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (180, 59, 3, 'Bày đậu hũ chiên ra đĩa rồi rưới ngập lớp sốt mè rang béo bùi lên trên.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (181, 60, 1, 'Đậu hũ cắt miếng vuông dày chiên vàng đều bốn mặt cho dai ngon.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (182, 60, 2, 'Xếp đậu hũ và nấm rơm vào nồi đất, đổ nước dừa tươi ngập xâm xấp mặt đậu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (183, 60, 3, 'Thêm nước tương, tiêu sọ và kho trên lửa nhỏ liu riu cho nước dừa cạn sệt óng ánh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (184, 61, 1, 'Rửa sạch nấm đùi gà, cắt khoanh dày 2cm và khía vảy rồng hai mặt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (185, 61, 2, 'Áp chảo nấm với chút dầu thực vật cho hai mặt xém vàng nâu thơm phức.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (186, 61, 3, 'Nấu sốt tiêu đen với nước tương, ớt và chút bột năng rồi đổ vào nấm đảo đều 2 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (187, 62, 1, 'Trộn đều đậu hũ tán nhuyễn, nấm mèo, nấm bào ngư và thì là thái nhỏ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (188, 62, 2, 'Thêm bột bắp, hạt nêm chay và tiêu sọ rồi nặn thành từng viên chả dẹt tròn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (189, 62, 3, 'Chiên chả trong chảo dầu nóng cho vàng ruộm hai mặt rồi vớt ra thấm ráo dầu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (190, 63, 1, 'Xào thơm cần tây và cà rốt với chút dầu ăn cho dậy mùi thơm ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (191, 63, 2, 'Thêm đậu lăng đỏ và nước lọc đun sôi rồi hạ lửa hầm mềm trong 20 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (192, 63, 3, 'Nêm chút muối tiêu vừa khẩu vị, dùng nóng như món khai vị ấm áp giàu năng lượng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (193, 64, 1, 'Luộc đậu gà chín bở mềm rồi vớt ra để ráo nước.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (194, 64, 2, 'Cho đậu gà vào nồi đất cùng nước tương, chút mật mía và tiêu hạt đập dập.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (195, 64, 3, 'Kho lửa nhỏ cho nước sốt ngấm sâu vào từng hạt đậu gà sánh keo óng ả.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (196, 65, 1, 'Rửa sạch quả đậu nành lông với nước muối loãng rồi để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (197, 65, 2, 'Đun sôi nồi nước với chút muối biển hạt to rồi thả đậu nành vào luộc 5 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (198, 65, 3, 'Vớt ra xả nước đá lạnh để giữ màu xanh mướt và thưởng thức hạt đậu bùi ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (199, 66, 1, 'Trộn ruột đậu hũ cùng nấm rơm, nấm mèo và gia vị tiêu sọ làm nhân.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (200, 66, 2, 'Nhồi nhân đầy đặn vào từng miếng đậu hũ chiên rồi chiên lại cho se mặt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (201, 66, 3, 'Xào sốt nước tương với hành boa-rô rồi cho đậu nhồi vào rim nhỏ lửa 10 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (202, 67, 1, 'Trộn bắp non bào nhuyễn cùng đậu xanh hấp chín, tiêu sọ và chút đường.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (203, 67, 2, 'Cuộn nhân thật chặt tay vào từng miếng bánh tráng gạo nhỏ nhắn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (204, 67, 3, 'Chiên ngập dầu trên lửa vừa cho cuốn chả ram chín vàng ruộm đều các mặt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (205, 68, 1, 'Đun sôi nước me lọc lấy nước cốt chua thanh tự nhiên cho vào nồi canh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (206, 68, 2, 'Thả cà chua, bắp chuối và rau muống vào nấu sôi bùng trên lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (207, 68, 3, 'Nêm gia vị chay vừa vặn, rắc ngò gai rau ngổ thơm lừng rồi tắt bếp ngay.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (208, 69, 1, 'Xào sơ cà chua và thơm với chút dầu ăn tạo màu đỏ cam bắt mắt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (209, 69, 2, 'Đổ nước dùng vào đun sôi cùng nước cốt me chua và nấm rơm ngọt nước.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (210, 69, 3, 'Cho dọc mùng đã bóp muối rửa sạch vào đun sôi lại 1 phút rồi múc ra bát.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (211, 70, 1, 'Trộn đậu hũ tán nhuyễn cùng nấm rơm băm nhỏ, nấm mèo và tiêu sọ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (212, 70, 2, 'Nhồi nhân vào từng khúc khổ qua rồi miết phẳng mặt hai đầu miếng khổ qua.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (213, 70, 3, 'Thả khổ qua vào nồi nước dùng hầm củ cải đun sôi lửa nhỏ đến khi khổ qua mềm ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (214, 71, 1, 'Nấu nước hầm rau củ cùng hạt sen tươi cho chín bở ngọt nước.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (215, 71, 2, 'Thả đậu hũ non và rong biển vào nấu sôi lăn tăn trên lửa nhỏ 2 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (216, 71, 3, 'Thêm vài lát gừng tươi thái sợi ấm áp rồi tắt bếp múc ra tô thưởng thức.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (217, 72, 1, 'Xào thơm nấm rơm với chút dầu ăn và hạt nêm chay cho dậy mùi ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (218, 72, 2, 'Đổ nước vào đun sôi bùng rồi cho rau ngót đã vò dập vào nấu nhanh trên lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (219, 72, 3, 'Nếm lại vừa khẩu vị, khi canh vừa sôi lại thì tắt bếp ngay để rau giữ màu xanh tươi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (220, 73, 1, 'Dùng muỗng nạo khoai mỡ thành hỗn hợp nhuyễn mịn dẻo quánh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (221, 73, 2, 'Xào sơ nấm bào ngư với chút hành boa-rô cho thơm rồi trút nước vào nấu sôi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (222, 73, 3, 'Hạ lửa từ từ múc từng muỗng khoai mỡ vào khuấy đều tay cho canh sánh dẻo thơm nồng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (223, 74, 1, 'Đậu phộng ngâm nước ấm rồi giã dập cho tiết vị sữa béo ngậy.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (224, 74, 2, 'Đun sôi nước với đậu phộng trên lửa vừa trong 10 phút cho đậu phộng chín bùi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (225, 74, 3, 'Thả bí đỏ vào nấu đến khi bí chín mềm dẻo, rắc ngò gai thái nhỏ lên mặt canh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (226, 75, 1, 'Đun sôi nồi nước dùng rau củ với vài lát gừng tươi thái chỉ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (227, 75, 2, 'Thả cải bẹ xanh vào nấu trên lửa lớn cho canh sôi bùng giữ màu xanh non.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (228, 75, 3, 'Nêm chút muối hạt và hạt nêm chay vừa miệng rồi tắt bếp múc ra tô ngay.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (229, 76, 1, 'Xào mềm cà chua tạo nước canh màu đỏ đẹp rồi châm nước đun sôi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (230, 76, 2, 'Thả bắp cải và đậu hũ vào nấu sôi chín tới cho bắp cải giữ độ giòn ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (231, 76, 3, 'Nêm gia vị chua ngọt thanh dịu, rắc chút hành hoa chay lên bát canh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (232, 77, 1, 'Xay nhuyễn bí đỏ chín cùng đậu gà, hạt sen và chút nước hầm rau củ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (233, 77, 2, 'Đổ hỗn hợp súp ra nồi đun nóng nhẹ trên lửa nhỏ liu riu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (234, 77, 3, 'Rưới nước cốt dừa tạo vân kem đẹp mắt và thưởng thức khi súp còn ấm áp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (235, 78, 1, 'Xào nấm rơm với chút dầu ăn cho thơm ngọt rồi thêm nước đun sôi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (236, 78, 2, 'Thả mướp hương và rau mồng tơi vào nấu nhanh trên lửa lớn 2 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (237, 78, 3, 'Khi mướp vừa chín tới tỏa hương ngào ngạt thì nêm nếm gia vị rồi tắt bếp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (238, 79, 1, 'Nấu củ sen cùng cà rốt và nấm đông cô trong nồi nước dùng trên lửa vừa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (239, 79, 2, 'Hầm liu riu 20 phút cho củ sen bở bùi và tiết vị ngọt đậm đà thanh mát.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (240, 79, 3, 'Nêm hạt nêm chay và rắc chút tiêu trắng thơm dịu trước khi múc ra bát.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (241, 80, 1, 'Nấu bắp ngọt và bông cải xanh trong nước hầm rau củ cho chín mềm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (242, 80, 2, 'Thêm nấm kim châm cắt khúc ngắn vào nấu sôi lăn tăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (243, 80, 3, 'Khuấy nhẹ chút bột bắp tạo độ sánh trong veo cho súp rồi múc ra bát dùng nóng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (244, 81, 1, 'Hầm hạt sen tươi cùng cà rốt trong nước dùng ngọt thơm 15 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (245, 81, 2, 'Thả nấm bào ngư vào nấu thêm 5 phút cho nấm chín mềm ngọt nước.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (246, 81, 3, 'Nêm gia vị vừa ăn, múc canh nóng ra tô dùng bồi bổ cơ thể.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (247, 82, 1, 'Nấu nước sôi dầm me quả lấy nước chua thanh lọc bỏ hạt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (248, 82, 2, 'Cho cà chua, đậu hũ non và rau muống vào nấu sôi bùng trên lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (249, 82, 3, 'Nếm vị chua dịu ngọt thanh vừa miệng rồi múc ra bát ăn cùng cơm trắng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (250, 83, 1, 'Ngó sen và cà rốt bào sợi vắt ráo nước trộn cùng sốt chanh đường ớt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (251, 83, 2, 'Thêm nấm tuyết đã chần sơ giòn dai vào trộn đều tay cho ngấm vị.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (252, 83, 3, 'Bày nộm ra đĩa, rắc đậu phộng rang vàng và rau răm thơm ngát lên trên.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (253, 84, 1, 'Củ hũ dừa bào lát mỏng ngâm nước đá chanh cho giữ độ giòn trắng nõn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (254, 84, 2, 'Pha nước sốt trộn gỏi từ nước tắc, đường thốt nốt, ớt băm và nước mắm chay.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (255, 84, 3, 'Trộn củ hũ dừa, đậu hũ chiên sợi với sốt rồi rắc đậu phộng rang bùi béo lên đĩa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (256, 85, 1, 'Bắp chuối bào mỏng ngâm nước chanh loãng vớt ra vắt thật ráo nước.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (257, 85, 2, 'Trộn xoài xanh, bắp chuối và cà rốt cùng nước mắm chua cay ngọt đậm đà.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (258, 85, 3, 'Dọn gỏi ra đĩa sâu lòng, rắc thật nhiều đậu phộng rang giòn thơm lừng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (259, 86, 1, 'Đu đủ xanh và cà rốt bào sợi ngâm nước đá cho giòn rụm rồi vắt ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (260, 86, 2, 'Làm bò khô chay từ sườn đậu nành xé sợi tẩm ướp ngũ vị chiên giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (261, 86, 3, 'Trộn đu đủ với nước giấm đường ớt, bày bò khô chay và đậu phộng lên mặt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (262, 87, 1, 'Luộc bông cải xanh, cà rốt và đậu que trong nước sôi có chút muối hạt cho giữ màu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (263, 87, 2, 'Vớt rau củ ra ngâm nước đá lạnh 2 phút rồi bày biện đẹp mắt lên đĩa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (264, 87, 3, 'Tán nhuyễn viên chao với đường, ớt tươi và mè rang làm sốt chấm béo bùi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (265, 88, 1, 'Làm ướt bánh tráng gỏi cuốn đặt lên mặt đĩa sạch.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (266, 88, 2, 'Xếp rau xà lách, dưa leo, bún tươi và thanh đậu hũ chiên vào cuộn thật chặt tay.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (267, 88, 3, 'Pha tương đen xào cùng bơ đậu phộng béo ngậy chấm cùng gỏi cuốn thanh mát.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (268, 89, 1, 'Bắp cải tím bào sợi mỏng ngâm nước muối loãng rồi rửa sạch vắt ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (269, 89, 2, 'Pha nước sốt giấm đường, tỏi ớt băm nhuyễn và hạt nêm chay vừa ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (270, 89, 3, 'Bóp nhẹ bắp cải với nước sốt, trộn thêm đậu hũ chiên sợi và rắc đậu phộng thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (271, 90, 1, 'Cắt khối quả bơ chín mềm, cà chua và dưa leo cho vào âu trộn lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (272, 90, 2, 'Pha sốt dầu giấm từ dầu oliu, giấm táo, chút muối tiêu và mật mía.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (273, 90, 3, 'Rưới đều sốt dầu giấm lên âu salad, đảo thật nhẹ tay tránh làm nát bơ.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (274, 91, 1, 'Tách từng tép bưởi hồng mọng nước cho vào tô lớn tránh làm dập tép bưởi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (275, 91, 2, 'Thêm rong biển đã chần sơ cắt sợi và đậu hũ chiên sợi vào tô.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (276, 91, 3, 'Trộn nhẹ cùng nước cốt tắc pha chua ngọt và rắc mè rang vàng lên đĩa gỏi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (277, 92, 1, 'Rau càng cua nhặt sạch ngâm nước muối rồi vớt ra để thật ráo nước.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (278, 92, 2, 'Chiên vàng giòn các viên đậu hũ cắt hạt lựu rồi để ráo dầu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (279, 92, 3, 'Trộn nhanh tay rau càng cua với dầu giấm chua ngọt, xếp đậu hũ chiên giòn lên trên.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (280, 93, 1, 'Rửa sạch nấm rơm, ngâm nước muối loãng rồi vớt ra để ráo nước hoàn toàn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (281, 93, 2, 'Phi thơm hành boa-rô, cho nấm rơm vào xào săn trên lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (282, 93, 3, 'Thêm nước tương, đường thốt nốt và tiêu xanh đập dập kho liu riu cho nước keo đặc.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (283, 94, 1, 'Cắt cà tím thành khúc vừa ăn, ngâm nước muối loãng để không bị thâm đen.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (284, 94, 2, 'Áp chảo sơ các mặt cà tím cho vàng xém thơm dịu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (285, 94, 3, 'Xếp cà tím vào tộ đất, rưới sốt tương bần pha gừng ớt rồi kho nhỏ lửa 15 phút.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (286, 95, 1, 'Khía mặt nấm đùi gà rồi chiên sơ trên chảo cho vàng mặt ngoài.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (287, 95, 2, 'Phi thơm sả băm, gừng thái chỉ với chút dầu ăn cho bốc mùi thơm ấm áp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (288, 95, 3, 'Cho nấm vào nồi đất cùng nước tương, ớt tươi kho lửa nhỏ cho nước sốt cạn sệt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (289, 96, 1, 'Nhặt rau muống lấy ngọn non, chần sơ qua nước sôi ngập muối rồi xả nước lạnh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (290, 96, 2, 'Phi vàng thơm hành boa-rô trên chảo dầu nóng lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (291, 96, 3, 'Trút rau muống vào xào nhanh tay trên lửa lớn với hạt nêm chay trong 2 phút rồi tắt bếp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (292, 97, 1, 'Khổ qua bổ đôi nạo sạch ruột trắng bên trong rồi thái lát mỏng ngâm nước đá.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (293, 97, 2, 'Xào khổ qua trên lửa lớn với chút dầu ăn cho chín tái giữ độ giòn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (294, 97, 3, 'Nhẹ nhàng trút đậu hũ non vào đảo cùng gia vị nêm chay cho ngấm rồi dọn ra đĩa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (295, 98, 1, 'Tước xơ đậu que, rửa sạch rồi chần sơ qua nước sôi để đậu giữ màu xanh biếc.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (296, 98, 2, 'Xào thơm nấm đông cô với hành boa-rô cho chín mềm thơm phức.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (297, 98, 3, 'Trút đậu que vào xào lửa lớn với nước tương, trước khi tắt bếp rưới 1 muỗng dầu mè.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (298, 99, 1, 'Phi thơm hành boa-rô xào chín nấm bào ngư và cà rốt trên chảo nóng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (299, 99, 2, 'Cho bắp cải vào xào cùng trên lửa lớn cho bắp cải chín tới giữ độ giòn ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (300, 99, 3, 'Nêm hạt nêm chay và chút tiêu sọ xay rồi múc ra đĩa sâu lòng dùng với cơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (301, 100, 1, 'Mít non luộc chín gọt bỏ gai và cùi, cắt thành từng miếng tam giác vừa ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (302, 100, 2, 'Chiên sơ miếng mít non cho săn mặt rồi ướp với nghệ tươi, sả băm và nước tương.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (303, 100, 3, 'Cho mít vào nồi kho cùng nước dừa tươi trên lửa nhỏ đến khi nước kho sánh vàng óng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (304, 101, 1, 'Rửa sơ cải chua vắt ráo nước để giảm độ mặn và độ chua gắt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (305, 101, 2, 'Xào cà chua mềm tạo sốt sánh đỏ rồi cho cải chua vào đảo đều trên lửa lớn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (306, 101, 3, 'Thêm đậu hũ chiên vào xào chung nêm đường và hạt nêm chay cho hài hòa vị chua ngọt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (307, 102, 1, 'Rửa sạch nấm bào ngư, vắt nhẹ ráo nước rồi xé thành từng tai vừa ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (308, 102, 2, 'Phi thơm sả băm và ớt trên chảo dầu nóng cho vàng giòn dậy mùi thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (309, 102, 3, 'Cho nấm vào xào nhanh tay trên lửa lớn, rắc lá lốt thái chỉ đảo đều 30 giây rồi tắt bếp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (310, 103, 1, 'Cắt đậu hũ miếng vuông, chiên vàng các mặt trong chảo dầu rồi vớt ra để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (311, 103, 2, 'Phi thơm hành boa-rô với dầu, cho cà chua băm vào xào tới khi nhuyễn thành sốt, nêm muối và nước tương.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (312, 103, 3, 'Cho đậu hũ chiên vào chảo sốt, rim lửa nhỏ 5 phút cho đậu thấm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (313, 103, 4, 'Xới cơm ra đĩa, múc đậu hũ sốt cà chua bên cạnh và dùng nóng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (314, 104, 1, 'Ngâm tàu hũ ky cho mềm, để ráo, cắt miếng vừa ăn rồi chiên giòn, vớt ra để ráo dầu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (315, 104, 2, 'Phi thơm sả và ớt băm với dầu, cho nấm đông cô vào xào chín.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (316, 104, 3, 'Cho tàu hũ ky vào đảo đều, nêm nước tương và tiêu cho vừa ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (317, 104, 4, 'Dọn tàu hũ ky xào sả ớt ra đĩa, ăn cùng cơm trắng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (318, 105, 1, 'Vo sạch gạo lứt, ngâm 1 giờ rồi nấu chín thành cơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (319, 105, 2, 'Phi thơm hành tỏi với dầu, cho cà rốt và nấm rơm vào xào săn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (320, 105, 3, 'Cho đậu gà đã luộc chín vào, thêm nước tương và nửa chén nước, rim lửa nhỏ 10 phút cho thấm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (321, 105, 4, 'Xới cơm gạo lứt ra đĩa, múc đậu gà rim nấm bên cạnh, rắc tiêu và dùng nóng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (322, 106, 1, 'Cắt đậu hũ miếng vừa ăn, chiên vàng các mặt trong chảo dầu rồi vớt ra.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (323, 106, 2, 'Phi thơm hành tím với dầu trong nồi, cho 1 muỗng canh đường vào thắng nước màu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (324, 106, 3, 'Cho nấm đùi gà và đậu hũ chiên vào, thêm nước tương, tiêu xay và nửa chén nước, kho lửa nhỏ 15 phút tới khi nước sệt lại.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (325, 106, 4, 'Rắc thêm tiêu, dọn ra ăn cùng cơm trắng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (326, 107, 1, 'Ngâm gạo nếp 4 giờ cho nở, để ráo rồi đồ chín thành xôi.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (327, 107, 2, 'Ngâm tàu hũ ky cho mềm, xé miếng rồi chiên giòn, vớt ra để ráo dầu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (328, 107, 3, 'Xào nấm đông cô với dầu cho chín, nêm nước tương. Phi hành boa-rô với dầu làm mỡ hành.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (329, 107, 4, 'Rang khô đậu phộng rồi giã dập.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (330, 107, 5, 'Xới xôi ra đĩa, phủ tàu hũ ky và nấm xào, rưới mỡ hành, rắc đậu phộng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (331, 108, 1, 'Cắt đậu hũ miếng vừa ăn, chiên vàng rồi vớt ra để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (332, 108, 2, 'Phi thơm sả với dầu, cho bột cà ri vào xào thơm, thêm khoai lang và cà rốt đảo đều.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (333, 108, 3, 'Đổ nước vừa ngập, nấu 15 phút cho khoai mềm, cho đậu hũ và nước cốt dừa vào, đun sôi lại rồi nêm muối.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (334, 108, 4, 'Trụng bún tươi, cho vào tô và chan cà ri nóng lên trên.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (335, 109, 1, 'Cắt đậu hũ thành thanh, chiên vàng rồi vớt ra để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (336, 109, 2, 'Phi sả băm với dầu tới khi vàng thơm, cho đậu hũ vào đảo đều với sả.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (337, 109, 3, 'Rang khô đậu phộng rồi giã dập. Pha nước mắm chay với 1 muỗng canh đường, nước cốt chanh, tỏi và ớt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (338, 109, 4, 'Cho bún vào tô, thêm dưa leo, cà rốt, đậu hũ sả, rắc đậu phộng và rưới nước mắm chay, trộn đều khi ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (339, 110, 1, 'Luộc mì sợi trong nước sôi tới khi chín tới, xả nước lạnh rồi để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (340, 110, 2, 'Cắt đậu hũ miếng vừa ăn, chiên vàng rồi vớt ra.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (341, 110, 3, 'Phi tỏi với dầu, xào cà rốt và nấm đùi gà cho chín, thêm cải thìa đảo nhanh.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (342, 110, 4, 'Cho mì và đậu hũ vào, nêm nước tương, đảo đều trên lửa lớn tới khi mì thấm gia vị rồi tắt bếp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (343, 111, 1, 'Chiên vàng đậu hũ và tàu hũ ky đã ngâm mềm, vớt ra để ráo dầu.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (344, 111, 2, 'Phi tỏi với dầu, cho nấm rơm vào xào chín, thêm nước tương và 1 muỗng canh đường, nấu sệt thành sốt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (345, 111, 3, 'Trụng hủ tiếu và cải thìa qua nước sôi, để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (346, 111, 4, 'Cho hủ tiếu vào tô, rưới sốt nấm, xếp đậu hũ, tàu hũ ky và cải thìa lên trên, trộn đều khi ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (347, 112, 1, 'Cắt đậu hũ thành thanh dài, chiên vàng rồi vớt ra để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (348, 112, 2, 'Phi tỏi với dầu, cho nấm đùi gà xé sợi vào xào chín, nêm nước tương.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (349, 112, 3, 'Pha nước chấm từ nước tương, 1 muỗng canh đường, nước cốt chanh, tỏi và ớt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (350, 112, 4, 'Trải từng miếng bánh phở, xếp đậu hũ, nấm, dưa leo và rau thơm lên rồi cuộn chặt.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (351, 112, 5, 'Xếp phở cuốn ra đĩa, chấm nước chấm khi ăn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (352, 113, 1, 'Ngâm đậu gà 8 giờ cho nở, luộc khoảng 40 phút tới khi chín mềm rồi để ráo.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (353, 113, 2, 'Phi thơm hành tỏi với dầu, cho cà chua băm vào xào nhuyễn.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (354, 113, 3, 'Cho khoai tây, cà rốt và đậu gà vào, đổ nước vừa ngập, hầm lửa nhỏ 20 phút tới khi khoai mềm, nêm muối và nước tương.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (355, 113, 4, 'Xới cơm ra đĩa, múc đậu gà hầm bên cạnh và dùng nóng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (356, 114, 1, 'Phi thơm hành tây với dầu, cho bột cà ri vào xào thơm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (357, 114, 2, 'Cho đậu lăng và bí đỏ vào, đổ nước ngập gấp đôi, nấu lửa nhỏ 25 phút tới khi đậu nhừ và nước sệt lại, nêm muối.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (358, 114, 3, 'Cho rau chân vịt vào đảo tới khi rau vừa mềm thì tắt bếp.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (359, 114, 4, 'Xới cơm ra đĩa, múc cà ri đậu lăng bên cạnh và dùng nóng.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (360, 115, 1, 'Vo sạch gạo lứt, ngâm 1 giờ, nấu chín cùng đậu đỏ đã ninh mềm.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (361, 115, 2, 'Rang khô mè tới khi vàng thơm, giã dập cùng muối làm muối mè.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (362, 115, 3, 'Áp chảo đậu hũ với dầu cho vàng hai mặt, luộc cải thìa.');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`) VALUES (363, 115, 4, 'Xới cơm gạo lứt đậu đỏ ra đĩa, rắc muối mè, ăn cùng đậu hũ và cải thìa.');
